def transform(grid):
    h,w=len(grid),len(grid[0])
    def score(lines):
        best=0
        for line in lines:
            run=0
            for x in line:
                run=run+1 if x else 0
                best=max(best,run)
        return best
    horizontal=score(grid)
    vertical=score(zip(*grid))
    if horizontal>vertical:
        return [[0]*(w-len(a))+a for row in grid for a in [[x for x in row if x]]]
    out=[[0]*w for _ in range(h)]
    for c in range(w):
        a=[grid[r][c] for r in range(h) if grid[r][c]]
        for r,x in enumerate(a,h-len(a)): out[r][c]=x
    return out

